import numpy as np
def maskcrop(g,c):
    ys=[p[0] for p in c];xs=[p[1] for p in c]
    return np.array([[g[y][x]==0 for x in range(min(xs),max(xs)+1)] for y in range(min(ys),max(ys)+1)])
for name in ['Demo pair 1','Demo pair 2']:
    g=G[name+' input'];o=G[name+' output']
    cs=comps_of(g)
    A=maskcrop(g,cs[0]);B=maskcrop(g,cs[1])
    ops={'AND':A&B,'OR':A|B,'XOR':A^B,'diff':(A+B)%2}
    om=np.array(o)
    # try all pairwise combos of op results AND their complements, check equality with outmask
    for nm,M in ops.items():
        for M2 in [M,~M]:
            rxs=np.where(M2.any(axis=1))[0]
            if len(rxs)==0: continue
            cxs=np.where(M2.any(axis=0))[0]
            cr=M2[rxs.min():rxs.max()+1,cxs.min():cxs.max()+1]
            if cr.shape==om.shape and (cr==om).all(): print(name,nm,'MATCH (orig)',np.flipud(cr))
